steps.run:
if [ -n "$SOURCE_COMMIT" ]; then
  node --input-type=module <<'JS'
import fs from 'node:fs';
import { validateHistorySelection } from './publisher/tools/shot/export-history-evidence.mjs';
if (process.env.RUN_ID || process.env.ARTIFACT_NAME) throw new Error('Choose historical Git evidence OR a CI artifact');
const paths = validateHistorySelection(process.env.SOURCE_COMMIT, JSON.parse(process.env.SOURCE_PATHS || '[]'));
fs.writeFileSync(`${process.env.RUNNER_TEMP}/evidence-history.json`, JSON.stringify({ sha: process.env.SOURCE_COMMIT, paths }));
fs.appendFileSync(process.env.GITHUB_OUTPUT, `sha=${process.env.SOURCE_COMMIT}\nmode=history\n`);
JS
  exit 0
fi
[ -n "$ARTIFACT_NAME" ] || { echo 'artifact_name is required for a CI capture'; exit 1; }
[[ "$RUN_ID" =~ ^[1-9][0-9]*$ ]] || { echo 'run_id must be numeric'; exit 1; }
gh api "repos/$GITHUB_REPOSITORY/actions/runs/$RUN_ID" > "$RUNNER_TEMP/evidence-run.json"
node --input-type=module <<'JS'
import fs from 'node:fs';
const run = JSON.parse(fs.readFileSync(`${process.env.RUNNER_TEMP}/evidence-run.json`));
if (run.repository?.full_name !== process.env.GITHUB_REPOSITORY || run.status !== 'completed' || !/^[a-f0-9]{40}$/.test(run.head_sha)) {
  throw new Error('Select a completed run from this repository with a valid source SHA');
}
fs.appendFileSync(process.env.GITHUB_OUTPUT, `sha=${run.head_sha}\nmode=artifact\n`);
JS

node --input-type=module <<'JS'
import fs from 'node:fs';
import path from 'node:path';
import { prepareEvidence, publishEvidence } from './publisher/tools/shot/publish-evidence.mjs';
import { exportHistoryEvidence } from './publisher/tools/shot/export-history-evidence.mjs';
const historical = process.env.SOURCE_MODE === 'history';
const run = historical ? null : JSON.parse(fs.readFileSync(`${process.env.RUNNER_TEMP}/evidence-run.json`));
const root = path.resolve('capture');
const artifactRoot = path.join(root, 'artifacts');
const dir = path.join(root, 'artifacts/promoted-evidence');
if (fs.existsSync(artifactRoot) && fs.lstatSync(artifactRoot).isSymbolicLink()) throw new Error('Captured artifacts/ must not be a symlink');
if (fs.existsSync(dir)) throw new Error('Capture checkout already contains the promotion directory');
// Extract outside both checkouts, then copy without following links.
// prepareEvidence rejects any copied symlinks before reading files.
let exported;
if (historical) {
  const selection = JSON.parse(fs.readFileSync(`${process.env.RUNNER_TEMP}/evidence-history.json`));
  exported = exportHistoryEvidence({ root, ...selection });
} else {
  fs.cpSync(`${process.env.RUNNER_TEMP}/evidence-download`, dir, { recursive: true, dereference: false, errorOnExist: true, force: false });
  const origin = path.join(dir, '_evidence-promotion.json');
  fs.writeFileSync(origin, JSON.stringify({ workflowRunUrl: run.html_url, runId: run.id, runAttempt: run.run_attempt, event: run.event, workflowHeadRepository: run.head_repository?.full_name, workflowRunHeadSha: run.head_sha, captureSourceSha: null, captureSourceVerification: 'unverified; consult producer metadata or checkout logs', artifactName: process.env.ARTIFACT_NAME }, null, 2), { flag: 'wx' });
}
if (!historical && process.env.DIRECT_IMAGES === 'true') throw new Error('direct_images applies only to selected historical Git evidence');
const linkableFiles = historical && process.env.DIRECT_IMAGES === 'true' ? exported.origin.files.filter((f) => /\.(png|jpe?g|webp|gif|avif)$/i.test(f.path)).map((f) => f.path) : undefined;
const bundle = prepareEvidence({ root, dir, label: process.env.LABEL, linkableFiles });
const result = publishEvidence(bundle.receiptPath);
fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, [
  '## Published evidence', '',
  `[Evidence release](${result.url})`, '',
  ...result.assets.map((a) => `- [${a.name}](${a.url})`), '',
  `Packaging checkout (workflow-run head): ${result.sourceSha}`,
  'Captured revision: **unverified**; consult the original producer metadata or checkout logs.',
  historical ? `Original Git evidence commit: ${result.sourceSha}` : `[Original capture run](${run.html_url})`, '',
].join('\n'));
console.log(JSON.stringify(result, null, 2));
JS

set -u
node <<'NODE'
const fs = require("fs");
const shard = +process.env.SHARD;
const shards = +process.env.SHARDS;
const pkgPath = "package.json";
const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
const all = String(pkg.scripts["test:sweeps"] || "").match(/tests\/unit\/[^\s]+/g) || [];
if (!all.length) {
  console.error("package.json test:sweeps names ZERO suites");
  process.exit(1);
}
const { execFileSync } = require("child_process");
const plan = JSON.parse(execFileSync(process.execPath, [
  "tools/ci/sweep-shards.mjs", "--shard", String(shard), "--shards", String(shards), "--json",
], { encoding: "utf8" }));
const slice = plan.files;
const temp = process.env.RUNNER_TEMP || ".";
fs.writeFileSync(`${temp}/sweep-shard-slice.txt`, slice.length ? `${slice.join("\n")}\n` : "");
console.log(`--- suite shard ${shard}of${shards}: ${slice.length}/${all.length} suites (~${plan.seconds}s measured) ---`);
for (const s of slice) console.log(s);
console.log("--------------------");
pkg.scripts["test:sweeps"] = "node --test --test-timeout=900000 --test-concurrency=1" + (slice.length ? ` ${slice.join(" ")}` : "");
fs.writeFileSync(pkgPath, `${JSON.stringify(pkg, null, 2)}\n`);
fs.appendFileSync(process.env.GITHUB_OUTPUT, `count=${slice.length}\n`);
NODE

test "$SWEEPS_RESULT" = success || {
  test "$SWEEPS_RESULT" = skipped && test "$GEOMETRY" = false && test -z "$TARGETED"
}
